// 5/25 demo: openvocab 命中即触发声光报警 + 推送通知
const hits = (msg.payload && msg.payload.hits) || [];
if (hits.length === 0) return null;  // 防御 — 上游已过滤

const topHit = hits.sort((a,b) => b.conf - a.conf)[0];
const camera = msg.payload.camera || '未知';
const summary = `[${camera}] 命中 ${topHit.class} (conf=${topHit.conf.toFixed(2)})`;

const alarm = {
    topic: 'av/control',
    payload: {
        target: 'siren_strobe',
        action: 'on',
        params: { duration_s: 10, severity: topHit.conf > 0.7 ? 'high' : 'medium' },
        source: 'node-red-demo-b',
        evidence: summary
    }
};
const notify = {
    topic: 'av/control',
    payload: {
        target: 'notify_channel',
        action: 'push',
        params: { text: `⚠ 异常: ${summary}`, channel: 'oncall' },
        source: 'node-red-demo-b'
    }
};
const log = {
    topic: 'av/audit/log',
    payload: { type: 'openvocab_hit', summary, raw: msg.payload, ts: Date.now() }
};
return [[alarm], [notify], [log]];
